  data: ArrayBuffer,
): Promise<string> {
  return fileType === "pdf" ? parsePdf(data) : parseDocx(data);
}

function safeMetadata(resume: Resume, mimeType: string): ResumeFileMetadata {
  return {
    fileName: resume.fileName,
    mimeType,
    fileSize: resume.fileSize,
    fileType: resume.type,
    fileHash: resume.fileHash,
    status: resume.status,
  };
}

function extractionRecovery(metadata: ResumeFileMetadata): ResumeExtractionRecovery {
  return {
    code: "extraction-failed",
    action: ACTIONS.pasteText,
    metadata,
  };
}

function resumeName(fileName: string): string {
  const dot = fileName.lastIndexOf(".");
  return (dot > 0 ? fileName.slice(0, dot) : fileName).trim() || "Resume";
}

async function blobArrayBuffer(blob: Blob): Promise<ArrayBuffer> {
  if (typeof blob.arrayBuffer === "function") return blob.arrayBuffer();
  return new Response(blob).arrayBuffer();
}

async function normalizeStoredFile(storedFile: StoredFile): Promise<StoredFile> {
  const bytes = await blobArrayBuffer(storedFile.blob);
  return {
    ...storedFile,
    blob: new Blob([bytes], { type: storedFile.blob.type }),
  };
}

export class ResumeIngestionService {
  readonly #database: IDBDatabase;
  readonly #now: () => string;
  readonly #createId: () => string;
  readonly #parseText: ResumeIngestionDependencies["parseText"];
  readonly #logger: NonNullable<ResumeIngestionDependencies["logger"]>;

  constructor(
    database: IDBDatabase,
    dependencies: ResumeIngestionDependencies = {},
  ) {
    this.#database = database;
    this.#now = dependencies.now ?? (() => new Date().toISOString());
    this.#createId = dependencies.createId ?? (() => crypto.randomUUID());
    this.#parseText = dependencies.parseText ?? defaultParseText;
    this.#logger = dependencies.logger ?? (() => undefined);
  }

  async ingest(file: File): Promise<ResumeIngestionResult> {
    const fileType = validateFileMetadata(file);
    const data = await file.arrayBuffer();
    validateFileContents(file, fileType, new Uint8Array(data));
    const fileHash = await sha256(data);
    const timestamp = this.#now();
    assertAbsoluteIsoTimestamp(timestamp, "Resume.uploadedAt");

    let extractedText: string | undefined;
    try {
      const parsed = await this.#parseText!(fileType, data.slice(0));
      if (!parsed.trim()) throw new Error("No text layer");
      extractedText = parsed;
    } catch {
      extractedText = undefined;
    }

    const resumeId = this.#createId();
    const originalFileId = this.#createId();
    const status: Resume["status"] = extractedText
      ? "needs-review"
      : "extraction-failed";
    const resume: Resume = {
      id: resumeId,
      createdAt: timestamp,
      updatedAt: timestamp,
      name: resumeName(file.name),
      type: fileType,
      fileName: file.name,
      fileSize: file.size,
      fileHash,
      uploadedAt: timestamp,
      tags: [],
      note: "",
      status,
      ...(extractedText ? { textSource: "extracted" as const } : {}),
      originalFileId,
    };
    const originalBlob = await new Response(data, {
      headers: { "content-type": file.type || MIME_TYPES[fileType] },
    }).blob();
    const storedFile: StoredFile = {
      id: originalFileId,
      createdAt: timestamp,
      updatedAt: timestamp,
      ownerType: "resume",
      ownerId: resumeId,
      fileName: file.name,
      fileType,
      blob: originalBlob,
    };
    const textRecord: ResumeText | undefined = extractedText
      ? {
          id: this.#createId(),
          createdAt: timestamp,
          updatedAt: timestamp,
          resumeId,
          kind: "extracted",
          text: extractedText,
        }
      : undefined;
    const metadata = safeMetadata(resume, storedFile.blob.type);

    await runTransaction(
      this.#database,
      [STORE_NAMES.resumes, STORE_NAMES.originalFiles, STORE_NAMES.resumeTexts],
      "readwrite",
      async (transaction) => {
        const resumeStore = transaction.objectStore(STORE_NAMES.resumes);
        const duplicate = await requestToPromise<Resume | undefined>(
          resumeStore.index("fileHash").get(fileHash),
        );
        if (duplicate) {
          throw ingestionError(
            "duplicate-file",
            "This resume file was already imported.",
            ACTIONS.useExisting,
            metadata,
            duplicate.id,
          );
        }

        await requestToPromise(resumeStore.add(resume));
        await requestToPromise(
          transaction.objectStore(STORE_NAMES.originalFiles).add(storedFile),
        );
        if (textRecord) {
          await requestToPromise(
            transaction.objectStore(STORE_NAMES.resumeTexts).add(textRecord),
          );
        }
      },
    );

    if (textRecord) {
      this.#logger({ event: "resume-ingested", metadata });
      return { outcome: "needs-review", resume, extractedText: textRecord };
    }

    const recovery = extractionRecovery(metadata);
    this.#logger({ event: "resume-extraction-failed", metadata });
    return { outcome: "extraction-failed", resume, recovery };
  }

  async getOriginalFile(resumeId: string): Promise<StoredFile | undefined> {
    const storedFile = await runTransaction(
      this.#database,
      STORE_NAMES.originalFiles,
      "readonly",
      (transaction) =>
        requestToPromise<StoredFile | undefined>(
          transaction
            .objectStore(STORE_NAMES.originalFiles)
            .index("ownerType_ownerId")
            .get(["resume", resumeId]),
        ),
    );
    return storedFile ? await normalizeStoredFile(storedFile) : undefined;
  }

  async getDownloadData(resumeId: string): Promise<ResumeDownloadData> {
    const storedFile = await this.getOriginalFile(resumeId);
    if (!storedFile) {
      throw ingestionError(
        "original-file-missing",
        "The original resume file is unavailable.",
        ACTIONS.selectExisting,
        { fileName: "", mimeType: "", fileSize: 0 },
      );
    }
    return {
      blob: storedFile.blob,
      fileName: storedFile.fileName,
      mimeType: storedFile.blob.type || MIME_TYPES[storedFile.fileType],
    };
  }

  async retryExtraction(resumeId: string): Promise<ResumeIngestionResult> {
    const { resume, storedFile } = await runTransaction(
      this.#database,
      [STORE_NAMES.resumes, STORE_NAMES.originalFiles],
      "readonly",
      async (transaction) => {
        const foundResume = await requestToPromise<Resume | undefined>(
          transaction.objectStore(STORE_NAMES.resumes).get(resumeId),
        );
        const foundFile = await requestToPromise<StoredFile | undefined>(
          transaction
            .objectStore(STORE_NAMES.originalFiles)
            .index("ownerType_ownerId")
            .get(["resume", resumeId]),
        );
        return { resume: foundResume, storedFile: foundFile };
      },
    );

    if (!resume) {
      throw ingestionError(
        "resume-not-found",
        "The resume no longer exists.",
        ACTIONS.selectExisting,
        { fileName: "", mimeType: "", fileSize: 0 },
      );
    }
    if (!storedFile) {
      throw ingestionError(
        "original-file-missing",
        "The original resume file is unavailable.",
        ACTIONS.selectExisting,
        safeMetadata(resume, ""),
      );
    }

    const normalizedStoredFile = await normalizeStoredFile(storedFile);
    const data = await blobArrayBuffer(normalizedStoredFile.blob);
    let text: string;
    try {
      text = await this.#parseText!(resume.type, data.slice(0));
      if (!text.trim()) throw new Error("No text layer");
    } catch {
      const metadata = safeMetadata(resume, normalizedStoredFile.blob.type);
      const recovery = extractionRecovery(metadata);
      this.#logger({ event: "resume-extraction-failed", metadata });
      return { outcome: "extraction-failed", resume, recovery };
    }

    const timestamp = this.#now();
    assertAbsoluteIsoTimestamp(timestamp, "Resume.updatedAt");
    const updatedResume: Resume = {
      ...resume,
      status: "needs-review",
      textSource: "extracted",
      updatedAt: nextUpdatedTimestamp(timestamp, resume.updatedAt),
    };
    const textRecord: ResumeText = {
      id: this.#createId(),
      createdAt: timestamp,
      updatedAt: timestamp,
      resumeId,
      kind: "extracted",
      text,
    };

import { requestToPromise, runTransaction } from "../db/database";
import { STORE_NAMES } from "../db/schema";
import { assertAbsoluteIsoTimestamp } from "../db/timestamps";
import type { StoredFile } from "../db/types";

export type StoredFileInput = Omit<StoredFile, "id" | "createdAt" | "updatedAt">;

export interface BlobStoreDependencies {
  now?: () => string;
  createId?: () => string;
}

const MAX_FILE_SIZE = 25 * 1024 * 1024;

function validateInput(input: StoredFileInput): void {
  if (input.fileType !== "pdf" && input.fileType !== "docx") {
    throw new Error("Invalid original file type: only PDF and DOCX are supported");
  }
  if (
    typeof input.blob !== "object" ||
    typeof input.blob.size !== "number" ||
    typeof input.blob.type !== "string" ||
    typeof input.blob.slice !== "function"
  ) {
    throw new Error("Invalid original file Blob");
  }
  if (input.blob.size > MAX_FILE_SIZE) {
    throw new Error("Invalid original file size: maximum is 25 MB");
  }
}

export class BlobStore {
  readonly #database: IDBDatabase;
  readonly #now: () => string;
  readonly #createId: () => string;

  constructor(database: IDBDatabase, dependencies: BlobStoreDependencies = {}) {
    this.#database = database;
    this.#now = dependencies.now ?? (() => new Date().toISOString());
    this.#createId = dependencies.createId ?? (() => crypto.randomUUID());
  }

  async save(input: StoredFileInput): Promise<StoredFile> {
    validateInput(input);
    const timestamp = this.#now();
    assertAbsoluteIsoTimestamp(timestamp, "original file timestamp");
    const record: StoredFile = {
      ...input,
      id: this.#createId(),
      createdAt: timestamp,
      updatedAt: timestamp,
    };

    await runTransaction(
      this.#database,
      STORE_NAMES.originalFiles,
      "readwrite",
      (transaction) =>
        requestToPromise(
          transaction.objectStore(STORE_NAMES.originalFiles).add(record),
        ),
    );
    return record;
  }

  get(id: string): Promise<StoredFile | undefined> {
    return runTransaction(
      this.#database,
      STORE_NAMES.originalFiles,
      "readonly",
      (transaction) =>
        requestToPromise<StoredFile | undefined>(
          transaction.objectStore(STORE_NAMES.originalFiles).get(id),
        ),
    );
  }

  list(): Promise<StoredFile[]> {
    return runTransaction(
      this.#database,
      STORE_NAMES.originalFiles,
      "readonly",
      (transaction) =>
        requestToPromise<StoredFile[]>(
          transaction.objectStore(STORE_NAMES.originalFiles).getAll(),
        ),
    );
  }

  async delete(id: string): Promise<void> {
    await runTransaction(
      this.#database,
      STORE_NAMES.originalFiles,
      "readwrite",
      (transaction) =>
        requestToPromise(
          transaction.objectStore(STORE_NAMES.originalFiles).delete(id),
        ),
    );
  }
}
import { requestToPromise, runTransaction } from "../db/database";
import { STORE_NAMES, type StoreName } from "../db/schema";

export interface DataClearPreview {
  recordCounts: Record<StoreName, number>;
  totalRecords: number;
  structuredRecords: number;
  textRecords: number;
  texts: number;
  blobs: number;
  blobRecords: number;
}

export interface ClearAllOptions {
  confirmed?: boolean;
  confirmationWord?: string;
}

export interface ClearAllResult {
  cleared: boolean;
  error?: Error;
}

const ALL_STORES = Object.values(STORE_NAMES) as StoreName[];
export const CLEAR_CONFIRMATION_WORD = "DELETE";
const TEXT_STORES = new Set<StoreName>([
  STORE_NAMES.resumeTexts,
  STORE_NAMES.jobDescriptionTexts,
]);

type Snapshot = Record<StoreName, unknown[]>;

async function snapshotData(database: IDBDatabase): Promise<Snapshot> {
  return runTransaction(database, ALL_STORES, "readonly", async (tx) => {
    const result = {} as Snapshot;
    await Promise.all(
      ALL_STORES.map(async (storeName) => {
        result[storeName] = await requestToPromise<unknown[]>(
          tx.objectStore(storeName).getAll(),
        );
      }),
    );
    return result;
  });
}

export async function previewDataClear(database: IDBDatabase): Promise<DataClearPreview> {
  const snapshot = await snapshotData(database);
  const recordCounts = {} as Record<StoreName, number>;
  let totalRecords = 0;
  let textRecords = 0;
  let blobs = 0;
  let structuredRecords = 0;
  for (const storeName of ALL_STORES) {
    const count = snapshot[storeName].length;
    recordCounts[storeName] = count;
    if (storeName !== STORE_NAMES.sensitiveSettings) totalRecords += count;
    if (TEXT_STORES.has(storeName)) textRecords += count;
    if (storeName === STORE_NAMES.originalFiles) blobs = count;
    if (!TEXT_STORES.has(storeName) && storeName !== STORE_NAMES.originalFiles && storeName !== STORE_NAMES.sensitiveSettings) {
      structuredRecords += count;
    }
  }
  return {
    recordCounts,
    totalRecords,
    structuredRecords,
    textRecords,
    texts: textRecords,
    blobs,
    blobRecords: blobs,
  };
}

async function restoreSnapshot(database: IDBDatabase, snapshot: Snapshot): Promise<void> {
  await runTransaction(database, ALL_STORES, "readwrite", (tx) => {
    const requests: Promise<unknown>[] = [];
    for (const storeName of ALL_STORES) {
      const store = tx.objectStore(storeName);
      requests.push(requestToPromise(store.clear()));
      for (const record of snapshot[storeName]) {
        requests.push(requestToPromise(store.put(record)));
      }
    }
    return Promise.all(requests).then(() => undefined);
  });
}

export async function clearAllData(
  database: IDBDatabase,
  options: ClearAllOptions = {},
): Promise<ClearAllResult> {
  if (!options.confirmed && options.confirmationWord !== CLEAR_CONFIRMATION_WORD) {
    return { cleared: false };
  }

  let snapshot: Snapshot;
  const localStorageSnapshot: Record<string, string> = {};
  try {
    snapshot = await snapshotData(database);
    for (let index = 0; index < localStorage.length; index += 1) {
      const key = localStorage.key(index);
      if (key) localStorageSnapshot[key] = localStorage.getItem(key) ?? "";
    }
  } catch (cause) {
    return { cleared: false, error: cause instanceof Error ? cause : new Error(String(cause)) };
  }
  try {
    await runTransaction(database, ALL_STORES, "readwrite", async (tx) => {
      await Promise.all(
        ALL_STORES.map((storeName) =>
          requestToPromise(tx.objectStore(storeName).clear()),
        ),
      );
    });
    localStorage.clear();
    return { cleared: true };
  } catch (cause) {
    try {
      await restoreSnapshot(database, snapshot);
      localStorage.clear();
      for (const [key, value] of Object.entries(localStorageSnapshot)) {
        localStorage.setItem(key, value);
      }
    } catch (restoreError) {
      return { cleared: false, error: restoreError instanceof Error ? restoreError : new Error(String(restoreError)) };
    }
    return { cleared: false, error: cause instanceof Error ? cause : new Error(String(cause)) };
  }
}

export const SENSITIVE_SETTINGS_ID = "ai";
export const getDataClearPreview = previewDataClear;
export const clearAllLocalData = clearAllData;

